   art:String.raw`<svg viewBox="0 0 360 320" role="img" aria-label="لوحة فيها ثمانية أهداف مرقمة للوحدة" style="font-family:var(--font)" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="160" r="140" fill="#FBE6C4"/><rect x="92" y="44" width="176" height="244" rx="14" fill="#FBF6EE" stroke="#2C4A40" stroke-width="3"/><rect x="146" y="32" width="68" height="24" rx="8" fill="#2C4A40"/><text x="180" y="82" text-anchor="middle" font-size="15" font-weight="700" fill="#2C4A40" direction="rtl" unicode-bidi="embed">أهداف الوحدة</text><circle cx="244" cy="106" r="8.5" fill="#E8735A"/><text x="244" y="110.5" text-anchor="middle" font-size="11" font-weight="700" fill="#FBF6EE" direction="ltr" unicode-bidi="embed">1</text><rect x="110" y="102.5" width="118" height="7" rx="3.5" fill="#CFC6B4"/><circle cx="244" cy="128" r="8.5" fill="#F2C14E"/><text x="244" y="132.5" text-anchor="middle" font-size="11" font-weight="700" fill="#2C4A40" direction="ltr" unicode-bidi="embed">2</text><rect x="136" y="124.5" width="92" height="7" rx="3.5" fill="#CFC6B4"/><circle cx="244" cy="150" r="8.5" fill="#4FB3A9"/><text x="244" y="154.5" text-anchor="middle" font-size="11" font-weight="700" fill="#2C4A40" direction="ltr" unicode-bidi="embed">3</text><rect x="120" y="146.5" width="108" height="7" rx="3.5" fill="#CFC6B4"/><circle cx="244" cy="172" r="8.5" fill="#12855A"/><text x="244" y="176.5" text-anchor="middle" font-size="11" font-weight="700" fill="#FBF6EE" direction="ltr" unicode-bidi="embed">4</text><rect x="104" y="168.5" width="124" height="7" rx="3.5" fill="#CFC6B4"/><circle cx="244" cy="194" r="8.5" fill="#E8735A"/><text x="244" y="198.5" text-anchor="middle" font-size="11" font-weight="700" fill="#FBF6EE" direction="ltr" unicode-bidi="embed">5</text><rect x="98" y="190.5" width="130" height="7" rx="3.5" fill="#CFC6B4"/><circle cx="244" cy="216" r="8.5" fill="#F2C14E"/><text x="244" y="220.5" text-anchor="middle" font-size="11" font-weight="700" fill="#2C4A40" direction="ltr" unicode-bidi="embed">6</text><rect x="144" y="212.5" width="84" height="7" rx="3.5" fill="#CFC6B4"/><circle cx="244" cy="238" r="8.5" fill="#4FB3A9"/><text x="244" y="242.5" text-anchor="middle" font-size="11" font-weight="700" fill="#2C4A40" direction="ltr" unicode-bidi="embed">7</text><rect x="108" y="234.5" width="120" height="7" rx="3.5" fill="#CFC6B4"/><circle cx="244" cy="260" r="8.5" fill="#12855A"/><text x="244" y="264.5" text-anchor="middle" font-size="11" font-weight="700" fill="#FBF6EE" direction="ltr" unicode-bidi="embed">8</text><rect x="128" y="256.5" width="100" height="7" rx="3.5" fill="#CFC6B4"/></svg>`,
